// src/components/ElectionCountdown.js
import React, { useEffect, useState } from "react";

const ElectionCountdown = ({ language = "english" }) => {
  // 👉 Yahan apni upcoming election ki date/time set karo
  // Example: 1 May 2027, 8:00 AM IST
  const ELECTION_DATE = new Date("2027-05-01T08:00:00+05:30");

  const translations = {
    hindi: {
      heading: "आगामी चुनाव की उलटी गिनती",
      electionType: "अगला आम / विधान सभा चुनाव (डेमो)",
      electionDateLabel: "चुनाव तिथि:",
      statusUpcoming: "चुनाव शुरू होने में समय शेष:",
      statusLive: "चुनाव शुरू हो चुके हैं!",
      statusOver: "यह चुनाव सम्पन्न हो चुका है।",
      days: "दिन",
      hours: "घंटे",
      minutes: "मिनट",
      seconds: "सेकंड",
      note: "कृपया सटीक तिथि और समय के लिए भारत निर्वाचन आयोग (ECI) की आधिकारिक वेबसाइट देखें।",
      lastUpdatedPrefix: "लोकल सिस्टम समय के अनुसार",
    },
    english: {
      heading: "Countdown to Upcoming Election",
      electionType: "Next General / Assembly Election (Demo)",
      electionDateLabel: "Election Date:",
      statusUpcoming: "Time remaining until polls open:",
      statusLive: "Voting has started!",
      statusOver: "This election has already concluded.",
      days: "Days",
      hours: "Hours",
      minutes: "Minutes",
      seconds: "Seconds",
      note: "For exact dates and schedule, always verify on the official Election Commission (ECI) website.",
      lastUpdatedPrefix: "Based on your device time",
    },
  };

  const t = translations[language] || translations.english;

  const getTimeLeft = () => {
    const now = new Date().getTime();
    const target = ELECTION_DATE.getTime();
    const diff = target - now;

    if (diff <= 0) {
      return {
        days: 0,
        hours: 0,
        minutes: 0,
        seconds: 0,
        isOverOrLive: true,
      };
    }

    // diff in milliseconds -> d/h/m/s
    const secondsTotal = Math.floor(diff / 1000);
    const days = Math.floor(secondsTotal / (60 * 60 * 24));
    const hours = Math.floor((secondsTotal % (60 * 60 * 24)) / (60 * 60));
    const minutes = Math.floor((secondsTotal % (60 * 60)) / 60);
    const seconds = secondsTotal % 60;

    return {
      days,
      hours,
      minutes,
      seconds,
      isOverOrLive: false,
    };
  };

  const [timeLeft, setTimeLeft] = useState(getTimeLeft());

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft(getTimeLeft());
    }, 1000); // every second

    return () => clearInterval(timer);
  }, []);

  const formattedDate = ELECTION_DATE.toLocaleString(language === "hindi" ? "hi-IN" : "en-IN", {
    weekday: "short",
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });

  // election started/over message
  const statusText = timeLeft.isOverOrLive
    ? t.statusLive // demo: treat as "live" when time passed
    : t.statusUpcoming;

  return (
    <section className="countdown-section">
      <h2>{t.heading}</h2>

      <div className="election-info">
        <h3>{t.electionType}</h3>
        <p className="election-date">
          <strong>{t.electionDateLabel}</strong> {formattedDate}
        </p>
        <p className="election-status">{statusText}</p>
      </div>

      {!timeLeft.isOverOrLive && (
        <div className="countdown-timer">
          <div className="countdown-item">
            <span className="countdown-value">
              {timeLeft.days.toString().padStart(2, "0")}
            </span>
            <span className="countdown-label">{t.days}</span>
          </div>
          <div className="countdown-item">
            <span className="countdown-value">
              {timeLeft.hours.toString().padStart(2, "0")}
            </span>
            <span className="countdown-label">{t.hours}</span>
          </div>
          <div className="countdown-item">
            <span className="countdown-value">
              {timeLeft.minutes.toString().padStart(2, "0")}
            </span>
            <span className="countdown-label">{t.minutes}</span>
          </div>
          <div className="countdown-item">
            <span className="countdown-value">
              {timeLeft.seconds.toString().padStart(2, "0")}
            </span>
            <span className="countdown-label">{t.seconds}</span>
          </div>
        </div>
      )}

      <p className="countdown-note">
        {t.note}
        <br />
        <span className="last-updated">⏱ {t.lastUpdatedPrefix}</span>
      </p>
    </section>
  );
};

export default ElectionCountdown;
